(* [comment removed for export] *)
Lemma tag_frame_w : forall i c E1 E' (M1 M' : mem) model1 pe ce BLk, PSM2.foot_all i c 0%nat (SR.PS 0 [] [] []) (CC.TOther 0) = true -> PSYK.footw c = true ->
