Lemma tag_at_leaf : forall i c k ps1 t pv lv pe ce d BLk E1 E' (M1 M' : mem) model1 cc ps2,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv ->
  PSM2.foot_all i c 0%nat (SR.PS 0 [] [] []) (CC.TOther 0) = true -> nth i G.BLS [] = (pe, ce) :: BLk -> HAMB i E1 M1 model1 ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> (forall a : word, SGP.outside E' (CC.cp_F c) a -> M' a = M1 a) ->
  know_ok RSEGS E' M' (SR.ps_cells ps1) -> uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) ->
  PMR.rm_match cc M1 P ps2 -> PML.ps_st ps2 = uv E1 (PB4.pv_st pv) -> PSIU.TAGR i cc E1 ->
