Lemma rm_match_leaf : forall i c k ps1 t pv lv pe ce d BLk E1 E' (M1 M' : mem) model1 cc ps2,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv ->
  PSM2.foot_all i c 0%nat (SR.PS 0 [] [] []) (CC.TOther 0) = true -> nth i G.BLS [] = (pe, ce) :: BLk -> HAMB i E1 M1 model1 ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> (forall a : word, SGP.outside E' (CC.cp_F c) a -> M' a = M1 a) ->
  know_ok RSEGS E' M' (SR.ps_cells ps1) -> uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) ->
  PMR.rm_match cc M1 P ps2 -> PML.ps_st ps2 = uv E1 (PB4.pv_st pv) -> PSIU.TAGR i cc E1 ->
  (i = I_HLO -> PMR.c_st cc <> PML.ST_STRING) -> (i = I_L2 -> PMR.c_st cc <> PML.ST_STRING) ->
  PMR.rm_match cc M' P ps2.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S;0!2+_E+_C+_C!1+2!1,3|600;|30;!1+4!1+2!1,32%~R13!2+_E+_B+_B!2+_E5+_C!2+_E6+_C!2+_E7+_D!2'aN/SCFG_P;/I;!1'e:#G$i;R+6$c;R+_@$k;R+6$ps1;R+_A$t;R+g0$pv;R+_B$lv;R+_B$pe;R+_C$ce;R+_C$d;R+_D$BLk;R!1+00$E1;R+aH$E';R+aH$M1;R4$M';R4$model1;R+aI$cc;R+_N$ps2;R+_M$IL;R!7'g1'g2'g3#B#A#@#?#>$HLD;R!3+F!1+48!3'_F#C#B#@!2,_G8!4,_H7+_D!4,_H6+_C!4,_H5+_C!4,_H+_B+_B#>#=#<#;#:$K1;R!3+F+g4!1'g5#D,g6$Hfoot;R!3+F+^A!5'f;#E#D,^J!4,f<,A!1,\!2+_E+6+_C!1,\'f=!1,\+f>!1,f?,A,^B$HBL;R!3+F'fA!4'?'fA#F'aT!1,\0!3,^E0!4,_H+_C+_C#?#>#<$HA;R!@'aJ!2'aK/SCFG_P;/I;!2'aL/SCFG_P;/I;'aM9/M0c;!2'aO/SCFG_P;/I;!3'aP/SCFG_P;/I;/eg;!2'aQ/SCFG_P;/I;'aR!2'aS/SCFG_P;/I;'aT!3'aU/SCFG_P;/I;/eg;#G#<#:#8$HagE';R!3'aX'aM9#<$Hag;R!3'aX!1'fB#H#>#=$HF;R%a;R1%~R!3'fC#?!1'fD#J#1!3+F3!1#>#2!1#?#2$HKc;R!4'g7'b5#?#=!1'_K#H$AG1;R!3+F+5!2'dJ#@:!2'dJ#A:$HRM;R!4'eD#=#@!2'c3/SCFG_P;/I;#<$Hps2;R!3+F+5!1'_T#=!2'dJ#C!1'e:#I$HTG;R!3'cP#O#?#D$HHLO;R%~R!3+F+6#P'g8!1'`F!3+F+5!1'_S#A'`I$HL2;R%~R!3+F+6#Q'g9!1'`F!3+F+5!1'_S#B'`I!9'gM/SCFG_P;/I;#E#D#B#A!D'gN/SCFG_P;/I;/eg;/M0c;#R#Q#G#F#E#D#C#K#J#H#=#<#;#:#9#8!R'gO#R#Q#P#O#N#M#L#K#J#I#H#G#F#E#D#C#B#A#@#?#>#=#<#;#:#9#8#7#6#5#4#3#2#1#5").
Qed.

