(* [comment removed for export] *)
Lemma src_byte : forall i c k ps1 t st bv a pv lv pe ce d E1 E' R' (M1 M' : mem),
  is_leaf i c k ps1 t -> PSCW.lact i k = Some (st, Some bv, a) -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  SIM i E1 M1 ->
  exists cc (n : nat) evs al bd stack buf,
    let b := nth n (PSIU.w0 I) 0 in
    PSIU.rem I E1 (PB4.pv_wptr pv) (PSCW.OFF i) = b :: skipn (S n) (PSIU.w0 I) /\ PSCW.OFF i = 0 /\ n = Z.to_nat (uv E1 (PB4.pv_wptr pv) - seg) /\ (n < length (PSIU.w0 I))%nat /\
    uv E1 (PB4.pv_wptr pv) < wend /\
    PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) cc (b :: skipn (S n) (PSIU.w0 I)) evs al /\ PSIU.SYNC I eg evs al /\
    PMR.c_more cc = true /\ PMR.c_st cc = st /\ uv E1 (PB4.pv_st pv) = st /\ bv_unsigned (ev E' bv) = b /\ 0 <= b <= 255 /\
    ((SR.ps_pc ps1 =? PARENT) = false -> PMR.dispatch (PMR.c_st cc) (PMR.top cc) b = a) /\
    ((SR.ps_pc ps1 =? PARENT) = true -> exists b0, PSCW.leaf_b0 i k = Some b0 /\ forall p, PMR.dispatch (PMR.c_st cc) p b = PMR.dispatch st p b0) /\
    PSIU.contents I pv pe ce E1 M1 true bd stack buf /\ Forall (fun x => 0 <= x <= 255) stack /\ (st = PML.ST_STRING -> L5.bytes_at RSEGS M1 (uv E1 pe) buf) /\
