Lemma exit_inv_w : forall i c k ps1 pv lv pe ce d E1 R1 E' R' (M1 M' : mem) model1 bm bd stack buf bufm,
  is_leaf i c k ps1 (CC.TOther RETPC) -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv -> i <> I_ENTRY ->
  CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> HAMB i E1 M' model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree GT.NF E0 E' ->
  SIM i E1 M1 -> PSIU.contents I pv pe ce E1 M1 bm bd stack buf -> uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) ->
  (uv E1 (PB4.pv_more pv) = 0 \/ wend <= uv E' (PB4.pv_wptr lv)) ->
  Forall (fun x => 0 <= x < 256) stack -> Z.of_nat (length bufm) = uv E1 (PB4.pv_size pv) ->
  let psc := PSIU.ps_of pv pe ce E1 bm bd stack buf in let w' := PB4.win_of (uv E' (PB4.pv_wptr lv)) wend in
  PML.parser_at M' P (PSS.upd psc (PML.ps_st psc) (PML.ps_sst psc) (PML.ps_nst psc) (PML.ps_more psc) bd (uv E1 ce) (uv E1 pe) bufm w') ->
