Lemma entry_facts : forall c k ps1 pc E1 E' R' (M1 M' Mx : mem) model1,
  is_leaf I_ENTRY c k ps1 (CC.TOther pc) -> (Z.eqb pc SETEC || Z.eqb pc POP)%bool = true ->
  HAMB I_ENTRY E1 Mx model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM I_ENTRY E1 M1 ->
  PSIU.w0 I = [] /\ PMR.c_st (PSIU.c0 I) = st0 /\ PMR.c_more (PSIU.c0 I) = true /\ (PMR.c_st (PSIU.c0 I) = PML.ST_NUMBER -> PMR.c_nst (PSIU.c0 I) = PSIU.nst0 I) /\
  PMRF.stack_ok (PSIU.c0 I) /\ PSIU.SYNC I eg [] 0 /\
