(* [comment removed for export] *)
Lemma setec_par_w : forall i c k ps1 E1 E' R' (M1 M' : mem) code,
  is_leaf i c k ps1 (CC.TOther SETEC) -> kind_of i = KParent ->
  env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM i E1 M1 ->
