(* [comment removed for export] *)
Lemma vec_w : forall i c k ps1 j cj pv lv pe ce d E1 E' R' (M1 M' : mem) E2 (M2 : mem) x bd stack buf bufT pvj,
  is_leaf i c k ps1 (CC.TOther VECPUSH) -> SR.ps_pc ps1 = VECPUSH -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv -> kind_of j = KVec -> PSM5.pushed_lit ps1 j = Some x -> PSM2.vw j = Some (pvj, pe, ce) ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  SIM i E1 M1 -> PSIU.contents I pv pe ce E1 M1 true bd stack buf -> Forall (fun z => 0 <= z < 256) stack ->
  PSIU.contents I pvj pe ce E2 M2 true bd (stack ++ [x]) bufT ->
  uv E2 (PB4.pv_wptr pvj) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d -> uv E2 (PB4.pv_st pvj) = uv E1 (PB4.pv_st pv) -> uv E2 (PB4.pv_sst pvj) = uv E1 (PB4.pv_sst pv) ->
