(* [comment removed for export] *)
Lemma pushb_w : forall i c k ps1 j cj pv lv pe ce d E1 E' R' (M1 M' : mem) E2 (M2 : mem) bd stack buf bufT pvj pej cej,
  is_leaf i c k ps1 (CC.TOther PUSHB) -> SR.ps_pc ps1 = PUSHB -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv -> kind_of j = KPushB -> PSM2.vw j = Some (pvj, pej, cej) ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree (CC.cp_nx cj - APC.NCS - 2) E' E2 ->
  SIM i E1 M1 -> PSIU.contents I pv pe ce E1 M1 true bd stack buf -> Forall (fun z => 0 <= z < 256) stack ->
  PSIU.contents I pvj pej cej E2 M2 true bd stack bufT ->
