Lemma parent_w : forall i c k ps1 j cj pv lv pe ce d E1 E' R' (M1 M' : mem) E2 (M2 : mem) bd stack buf rest x bufT,
  is_leaf i c k ps1 (CC.TOther PARENT) -> SR.ps_pc ps1 = PARENT -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> (kind_of i = KInv \/ kind_of i = KParent) -> kind_of j = KParent -> PSM2.vw j = Some (lv, pe, ce) ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree (CC.cp_nx cj - APC.NCS - 1) E' E2 ->
  SIM i E1 M1 -> PSIU.contents I pv pe ce E1 M1 true bd stack buf -> PML.wf_ps (PSIU.ps_of pv pe ce E1 true bd stack buf) -> stack = rest ++ [x] ->
  uv E2 (EVar (CC.cp_nx cj - APC.NCS - 1)) = x ->
  PSIU.contents I lv pe ce E2 M2 true bd stack bufT ->
