(* [comment removed for export] *)
Definition WREF (j : nat) (M' : mem) (ps2 : PML.pstate) (wp : Z) : Prop :=
  exists c evs al, PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) c (skipn (Z.to_nat (wp - seg + PSCW.OFF j)) (PSIU.w0 I)) evs al /\ PMR.rm_match c M' P ps2 /\ PSIU.SYNC I eg evs al /\
  (j = I_L2 -> PMR.c_st c <> PML.ST_STRING /\ PMR.c_st c <> PML.ST_NUMBER) /\ (j = I_HLO -> PMR.c_st c <> PML.ST_STRING).

(* [comment removed for export] *)
Definition TAGE (E2 : env) (M' : mem) : Prop := PML.u8 M' (P + 220) (uv E2 (EVar 69)) /\ 0 <= uv E2 (EVar 69) < 256.
Lemma wre_of_wref : forall j (M' : mem) ps2 wp pvj pej cej E2,
  WREF j M' ps2 wp -> PML.parser_at M' P ps2 -> Forall (fun x => 0 <= x < 256) (PML.ps_stack ps2) -> PML.ps_win ps2 = PB4.win_of wp wend -> seg <= wp <= wend ->
  PSM2.vw j = Some (pvj, pej, cej) -> kind_of j = KInv -> j <> I_ENTRY ->
  PSIU.ps_of pvj pej cej E2 (PML.ps_more ps2) (PML.ps_done ps2) (PML.ps_stack ps2) (PML.ps_buf ps2) = ps2 ->
  PSIU.contents I pvj pej cej E2 M' (PML.ps_more ps2) (PML.ps_done ps2) (PML.ps_stack ps2) (PML.ps_buf ps2) ->
