Lemma wref_keep : forall i c k ps1 j pv lv pe ce d E1 R1 E' R' (M1 M' : mem) model1 bm bd stack buf bufm w2 wp,
  is_leaf i c k ps1 (CC.TOther HPC) -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv ->
  CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> env_agree GT.NF E0 E' ->
  SIM i E1 M1 -> PSIU.contents I pv pe ce E1 M1 bm bd stack buf -> Forall (fun z => 0 <= z < 256) stack -> Z.of_nat (length bufm) = uv E1 (PB4.pv_size pv) ->
  PSCW.OFF j = 0 -> (j = I_HLO -> uv E1 (PB4.pv_st pv) <> PML.ST_STRING) -> j <> I_L2 -> wp = uv E1 (PB4.pv_wptr pv) ->
